const P = ctx.params;
const gateY = ctx.height - 34;
const valueGate = ctx.chip('= value', { color: ctx.colors.g1, textColor: 0x04101a, minWidth: 128, size: 13 });
valueGate.x = ctx.width * 0.26; valueGate.y = gateY;
const bodyGate = ctx.chip('{ body }', { color: ctx.colors.g3, textColor: 0x04101a, minWidth: 128, size: 13 });
bodyGate.x = ctx.width * 0.74; bodyGate.y = gateY;
const seam = new PIXI.Graphics();
seam.moveTo(ctx.width / 2, 18).lineTo(ctx.width / 2, gateY - 24).stroke({ width: 2, color: ctx.colors.dim, alpha: 0.28 });
ctx.stage.addChild(seam, valueGate, bodyGate);
let routed = 0, wrong = 0, done = false, chip = null, isStmt = false;
ctx.api.setGoal('0 / ' + P.target);
function spawn() {
  isStmt = Math.random() < 0.5;
  chip = ctx.chip(isStmt ? ctx.pick(P.stmt) : ctx.pick(P.expr), { color: isStmt ? ctx.colors.g2 : ctx.colors.g1, textColor: 0x04101a, size: 12 });
  chip.x = ctx.width / 2;
  chip.y = -16;
  ctx.stage.addChild(chip);
}
function shatter(x, y, msg) {
  for (let i = 0; i < 9; i++) {
    const s = new PIXI.Graphics();
    s.roundRect(-3, -3, 6, 6, 1).fill({ color: ctx.colors.bad });
    s.x = x; s.y = y;
    ctx.stage.addChild(s);
    gsap.to(s, { x: x + ctx.rand(-80, 80), y: y + ctx.rand(-46, 30), alpha: 0, duration: 0.55, onComplete: () => s.destroy() });
  }
  const note = ctx.text(msg, { size: 11, color: ctx.colors.bad, mono: true });
  note.anchor.set(0.5);
  note.x = ctx.width / 2;
  note.y = y - 30;
  ctx.stage.addChild(note);
  gsap.to(note, { alpha: 0, y: note.y - 20, duration: 1.2, onComplete: () => note.destroy() });
}
ctx.app.stage.eventMode = 'static';
ctx.app.stage.hitArea = new PIXI.Rectangle(0, 0, ctx.width, ctx.height);
ctx.app.stage.on('pointermove', (e) => { if (chip) chip.x = Math.max(90, Math.min(ctx.width - 90, e.global.x)); });
spawn();
ctx.onTick((dt) => {
  if (done || !chip) return;
  chip.y += 1.9 * dt;
  if (chip.y < gateY - 20) return;
  const toValue = chip.x < ctx.width / 2;
  const ok = toValue !== isStmt;
  const gate = toValue ? valueGate : bodyGate;
  const dead = chip;
  chip = null;
  if (ok) {
    routed++;
    ctx.api.setScore(routed);
    ctx.api.setGoal(routed + ' / ' + P.target);
    gsap.to(gate.scale, { x: 1.16, y: 1.16, duration: 0.1, onComplete: () => gsap.to(gate.scale, { x: 1, y: 1, duration: 0.22, ease: 'back.out' }) });
    gsap.to(dead, { alpha: 0, duration: 0.28, onComplete: () => dead.destroy() });
  } else {
    wrong++;
    shatter(dead.x, dead.y, toValue ? 'that is a statement - the value gate shatters' : 'that one produces a value - send it to = value');
    dead.destroy();
  }
  if (routed >= P.target) { done = true; ctx.api.win('Every fragment through a gate that accepts it.'); return; }
  if (wrong >= 3) { done = true; ctx.api.fail('Three parse errors. Keywords go through { body } only.'); return; }
  spawn();
});

