challenge.solution:
$tab = "list"
$rows = [{ title: "Invoice" }, { title: "Receipt" }]

function viewFor(tab) {
  switch (tab) {
    case "grid": return Grid($rows.map(r => Card([Text(r.title)])), { columns: 3 })
    default:     return List($rows.title)
  }
}

$app(Column([
  PageHeader("Documents", { breadcrumbs: false }),
  viewFor($tab)
]))

